using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 [InitializeOnLoad] public static class AlpsLevelChecks {
  const string Key="Snowglow.LevelChecks",Folder="Logs/TheAlps";static double next;static Vector3 start;static int checks;static string expectedSeed;static float fuel,condition;static int coins;
  static AlpsLevelChecks(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=state=>{if(state==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool(Key+".Active",false)){SessionState.SetBool(Key+".Active",false);SessionState.EraseString(Key+".Profile");var path=SessionState.GetString(Key+".Return","Assets/Scenes/Pinefall.unity");EditorSceneManager.OpenScene(path);}};}
  static void Check(bool ok,string why){checks++;if(!ok)throw new InvalidOperationException("Alps level checks: "+why);}
  static void Stage(int stage,float delay=1){SessionState.SetInt(Key+".Stage",stage);next=EditorApplication.timeSinceStartup+delay;}
  static void Tick(){try{
   if(!EditorApplication.isPlaying&&File.Exists(Folder+"Checks.request")&&!EditorApplication.isCompiling&&!EditorApplication.isUpdating&&!SessionState.GetBool(Key+".Active",false)){
    File.Delete(Folder+"Checks.request");Directory.CreateDirectory(Folder);var prior=SceneManager.GetActiveScene();Check(!prior.isDirty,"clean scene before test");SessionState.SetString(Key+".Return",prior.path);var scene=EditorSceneManager.OpenScene("Assets/Scenes/TheAlps.unity");AlpsTownAuthoring.Validate(scene);var s=UnityEngine.Object.FindFirstObjectByType<PrototypeSession>();var p=new ProfileSave{coins=4321,careerCompletedJobs=new[]{CareerProgression.Key("pinefall",0),CareerProgression.Key("pinefall",1),CareerProgression.Key("pinefall",2)},machines=s.Fleet.Select(m=>new MachineSave{id=m.definition.id,owned=true,fuel=m.definition.fuelCapacity*.6f,condition=75,tyres=1,engine=1}).ToArray()};Check(SaveStore.Decode(JsonUtility.ToJson(new ProfileSave{pendingTownStart=true})).pendingTownStart,"fresh-town start marker survives JSON roundtrip");Check(CareerProgression.TownIsUnlocked(p,"alps")&&CareerProgression.QuickJobs(p,new System.Random(7)).Length==4,"Alps unlock and unique Quick pool");SessionState.SetString(Key+".Profile",JsonUtility.ToJson(p));SessionState.SetBool(Key+".Active",true);SessionState.SetFloat(Key+".Started",(float)EditorApplication.timeSinceStartup);Stage(0);EditorApplication.isPlaying=true;return;
   }
   if(!SessionState.GetBool(Key+".Active",false)||!EditorApplication.isPlaying||EditorApplication.isCompiling||EditorApplication.isUpdating)return;
   if(EditorApplication.timeSinceStartup-SessionState.GetFloat(Key+".Started",0)>180)throw new TimeoutException("level Play test timed out");
   if(EditorApplication.timeSinceStartup<next)return;var game=PrototypeSession.Instance;if(!game||game.Profile==null||!game.Snow||!game.Active.Body)return;
   int stage=SessionState.GetInt(Key+".Stage",0);
   if(stage==0){checks=0;Check(game.TownId=="alps","direct Alps scene");Check(game.Fleet.All(m=>m.Owned&&m.Condition==75),"fleet state restore");game.StartJob(0,false,false,"alps");Check(game.IsRunning&&game.Profile.jobTownId=="alps"&&game.Snow.Progress<.15f,"Career starts uncleared in correct town");Stage(1,3);}
   else if(stage==1){Check(game.Active.transform.position.y>4&&game.Active.transform.position.y<9,"vehicle supported at depot");Check(game.Active.wheels.Count(w=>w.GetGroundHit(out var hit))>=2,"live wheel contacts");start=game.Active.transform.position;game.Active.Body.linearVelocity=game.Active.transform.forward*4;game.Input.Throttle=0;Stage(2,2);}
   else if(stage==2){Check(Vector3.Distance(start,game.Active.transform.position)>1,"unpowered vehicle coasts on authored surface");Check(game.Active.transform.position.y>4,"no fall through road");var b=SnowField.ContractBounds(0);for(int i=0;i<game.Snow.Grid.depth.Length;i++)if(CareerSnowState.Inside(b,game.Snow.Grid.X(i),game.Snow.Grid.Z(i)))game.Snow.Grid.depth[i]=0;game.Snow.Recount();game.Finish();Check(CareerProgression.Completed(game.Profile,"alps",0)&&CareerProgression.JobUnlocked(game.Profile,"alps",1),"Alps completion unlocks its next job");game.StartJob(1,false,false,"alps");Check(game.Snow.Grid.depth[game.Snow.Grid.Index(-44,-65)]<.07f,"completed Alps work stays cleared");Check(game.Snow.Progress<.15f,"next venue still snowed");game.Abandon();fuel=game.Active.Fuel;condition=game.Active.Condition;coins=game.Profile.coins;expectedSeed=AssetDatabase.GetAssetPath(game.Snow.seed);Stage(3,2);game.StartJob(0,false,false,"pinefall");}
   else if(stage==3){if(game.TownId!="pinefall")return;Check(game.IsRunning&&game.Profile.jobTownId=="pinefall","cross-town travel loads Pinefall and resumes: panel="+game.Panel+" inJob="+game.Profile.inJob+" profileTown="+game.Profile.jobTownId+" progress="+game.Snow.Progress);Check(AssetDatabase.GetAssetPath(game.Snow.seed)!=expectedSeed,"different scene snow assets");Check(game.Profile.coins==coins&&Mathf.Abs(game.Active.Fuel-fuel)<.05f&&Mathf.Abs(game.Active.Condition-condition)<.05f,"travel preserves economy and machine state");Check(CareerSnowState.Find(game.Profile,"alps")!=null,"Alps checkpoint retained through travel");game.Abandon();Stage(4,2);game.StartJob(0,false,true,"alps");}
   else if(stage==4){if(game.TownId!="alps")return;Check(game.IsRunning&&game.Profile.quickPlay&&game.Snow.Progress<.15f,"Quick travel returns to fresh Alps snow");game.Open("pause");game.Active.Body.linearVelocity=Vector3.one*3;game.Active.Body.angularVelocity=Vector3.one;game.Continue();Check(game.Active.Body.linearVelocity.sqrMagnitude<.0001f&&game.Active.Body.angularVelocity.sqrMagnitude<.0001f,"resume resets physics");game.Abandon();game.StartJob(1,false,false,"alps");Check(game.Snow.Grid.depth[game.Snow.Grid.Index(-44,-65)]<.07f,"Quick work does not replace Career clearance");game.Open("pause");File.WriteAllText(Folder+"/PlayChecks.txt","PASS: "+checks+" live assertions. Both scene transitions, independent seeds/checkpoints, Career completion/next venue, Quick fresh snow, coasting/wheel support, ownership/wallet/fuel/condition transfer, resume motion reset. Synthetic venue clearance tests progression, not physical job completion. Diagnostic profile was stored only in Editor SessionState; real profile writes suppressed. Phone acceptance remains separate.");EditorApplication.isPlaying=false;}
  }catch(Exception e){Directory.CreateDirectory(Folder);File.WriteAllText(Folder+"/PlayChecks.txt","FAIL: "+e);Debug.LogException(e);if(EditorApplication.isPlaying)EditorApplication.isPlaying=false;else{SessionState.SetBool(Key+".Active",false);SessionState.EraseString(Key+".Profile");}}}
 }
}
